head.script:
scwin.doInit = function() {
    grid.setCellReadOnly(3, 0, false);
    grid.setCellBackgroundColor(3, 0, "#ff0000");
    grid1.setCellDisabled(3, 0, false);
    grid1.setCellBackgroundColor(3, 0, "#ff0000");
}
scwin.trigger2_onclick = function(e) {
    dataList1.setRowJSON(
        4, {
            "col1": "e",
            "col2": "e1"
        }
    );
    grid.setCellReadOnly(4, 1, false);
    grid.setCellBackgroundColor(4, 1, "#0000ff");
};
scwin.trigger3_onclick = function(e) {
    dataList1.removeRow(3);
};
scwin.trigger5_onclick = function(e) {
    dataList2.setRowJSON(
        4, {
            "col1": "5",
            "col2": "a5"
        }
    );
    grid1.setCellDisabled(4, 1, false);
    grid1.setCellBackgroundColor(4, 1, "#0000ff");
};
scwin.trigger6_onclick = function(e) {
    dataList2.removeRow(3);
};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById(id);
    scwin.fireDbClick(el);
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid_body_tbody tr').not('.w2grid_hidedRow').length == 6", "true");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid_cell_3_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('grid_cell_3_0').innerText != 'd'", "true");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('grid_cell_3_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#G_grid__col2').css('display') == 'block'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_grid__col2').value = 'e2'");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid_cell_4_0').click()");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('grid_cell_3_1').innerText == 'e2'", "true");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger5').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger5').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_body_tbody tr').not('.w2grid_hidedRow').length == 6", "true");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_cell_3_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger6').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#grid1_body_tbody tr').not('.w2grid_hidedRow').length == 5", "true");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick('grid1_cell_3_1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#G_grid1__col2').css('display')", "block");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('G_grid1__col2').value = 'a6'");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_cell_4_0').click()");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('grid1_cell_3_1').innerText == 'a6'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
    scwin.doInit();
}
